export const Clock: React.FC = () => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timerId = setInterval(() => {
      setTime(new Date());
    }, 1000);

    return () => clearInterval(timerId);
  }, []);

  return (
    <div className="font-mono text-lg font-bold text-slate-800">
      {time.toLocaleTimeString()}
    </div>
  );
};
